#include <string>
#include <vector>

using namespace std;

class Solution {
    int lucas(int n, int k, int p) {
        int res = 1;
        while (n > 0 || k > 0) {
            int ni = n % p, ki = k % p;
            if (ni < ki) return 0;
            int comb = 1;
            for (int i = 0; i < ki; i++) {
                comb = comb * (ni - i) / (i + 1);
            }
            res = (res * (comb % p)) % p;
            n /= p;
            k /= p;
        }
        return res;
    }

    int nckMod10(int n, int k) {
        static const int lookup[2][5] = {
            {0, 6, 2, 8, 4},
            {5, 1, 7, 3, 9}
        };
        int m2 = lucas(n, k, 2);
        int m5 = lucas(n, k, 5);
        return lookup[m2][m5];
    }

public:
    bool hasSameDigits(string s) {
        int n = s.size();
        int m = n - 2;
        int num1 = 0, num2 = 0;
        for (int i = 0; i <= m; i++) {
            int c = nckMod10(m, i);
            num1 = (num1 + c * (s[i] - '0')) % 10;
            num2 = (num2 + c * (s[i + 1] - '0')) % 10;
        }
        return num1 == num2;
    }
};

