    const m = n - 2;
    const lookup = [
        [0, 6, 2, 8, 4],
        [5, 1, 7, 3, 9]
    ];

    function lucas(nVal, kVal, p) {
        let res = 1;
        while (nVal > 0 || kVal > 0) {
            const ni = nVal % p, ki = kVal % p;
            if (ni < ki) return 0;
            let comb = 1;
            for (let i = 0; i < ki; i++) {
                comb = Math.floor(comb * (ni - i) / (i + 1));
            }
            res = (res * (comb % p)) % p;
            nVal = Math.floor(nVal / p);
            kVal = Math.floor(kVal / p);
        }
        return res;
    }

    function nckMod10(nVal, kVal) {
        const m2 = lucas(nVal, kVal, 2);
        const m5 = lucas(nVal, kVal, 5);
        return lookup[m2][m5];
    }

    let num1 = 0, num2 = 0;
    for (let i = 0; i <= m; i++) {
        const c = nckMod10(m, i);
        num1 = (num1 + c * Number(s[i])) % 10;
        num2 = (num2 + c * Number(s[i + 1])) % 10;
    }
